#kiseki-v146-design .kiseki-section-title,
#kiseki-v146-design .kiseki-section-title :is(h2, h3, p, span, strong) {
    font-size: 30px !important;
    font-weight: 700 !important;
    line-height: 1.8;
    letter-spacing: .08em;
    text-align: left !important;
    overflow-wrap: anywhere;
}

#kiseki-v146-design .kiseki-section-title :is(h2, h3, p) {
    margin: 0;
    padding: 0;
    border: 0;
}

#kiseki-v146-design img,
#kiseki-v146-design video,
#kiseki-v146-fv img {
    display: block;
    width: 100%;
    max-width: 100%;
    height: auto;
    margin: 0 auto;
    vertical-align: bottom;
    object-fit: contain;
}

#kiseki-v146-design picture,
#kiseki-v146-fv picture {
    display: block;
}

#kiseki-v146-design video {
    background: #fff;
}

#kiseki-v146-design :is(p, h2, div):has(>br:only-child) {
    margin: 0;
    padding: 0;
    min-height: 0;
    height: 20px;
    line-height: 20px;
}

#kiseki-v146-design .marker.active {
    background: linear-gradient(transparent 55%, #fffbad 55%);
    box-decoration-break: clone;
    -webkit-box-decoration-break: clone;
}

#kiseki-v146-design p.note {
    font-size: 20px !important;
    line-height: 1.8;
}

#kiseki-v146-design sup {
    font-size: .55em;
    vertical-align: super;
}

#kiseki-v146-design .bg-ye:has(> .container-bg:empty) {
    display: none;
}

#kiseki-v146-fv .fv-bg-wht,
#kiseki-v146-fv h2 {
    margin: 0;
    padding: 0;
    line-height: 0;
}

#kiseki-v146-fv h2:first-child {
    display: none;
}

@media(max-width:600px) {
    #kiseki-v146-design {
        padding: 18px;
    }

    #kiseki-v146-design .container {
        margin: 36px 0;
    }

    /* Font sizes intentionally stay at 30px / 20px on smartphones. */
}

/* AUN kwy7kj: marked text uses literal 30pt (40px); regular section titles remain 30px. */
