#kiseki-b-design{box-sizing:border-box;width:100%;max-width:750px;margin:0 auto;padding:28px;border-left:2px solid #d8e5ee;border-right:2px solid #d8e5ee;background:#fff;color:#0f1419;font-family:"Noto Sans JP","Hiragino Kaku Gothic ProN","Yu Gothic",Meiryo,sans-serif;font-size:20px;line-height:2;letter-spacing:.05em;overflow-wrap:break-word}
#kiseki-b-design *{box-sizing:border-box}
#kiseki-b-design p{margin:24px 0;font-size:20px;font-weight:400;line-height:2}
#kiseki-b-design img,#kiseki-b-design video{display:block;width:100%;max-width:100%;height:auto;margin:0 auto;object-fit:contain}
#kiseki-b-design .b-brand{margin:0 0 28px;line-height:1.5;font-size:20px;font-weight:700;letter-spacing:.02em}
#kiseki-b-design .b-fv h1{margin:0 0 28px;text-align:center;line-height:1.65;letter-spacing:.05em;font-size:34px}
#kiseki-b-design .b-fv h1 span,#kiseki-b-design .b-fv h1 strong{display:block}
#kiseki-b-design .b-fv h1 strong{font-size:42px;color:#0f1419}
#kiseki-b-design .b-hero-image{margin:16px auto 26px}
#kiseki-b-design .b-fv-description{text-align:center}
#kiseki-b-design .b-product-name{margin:22px 0;font-size:40px;font-weight:700;letter-spacing:.04em;text-align:center}
#kiseki-b-design .b-cta{display:block;position:relative;width:100%;margin:30px auto;padding:17px 38px;background:#132a46;border:2px solid #132a46;border-radius:3px;color:#fff;text-align:center;font-size:24px;font-weight:700;line-height:1.5;text-decoration:none}
#kiseki-b-design .b-cta span{position:absolute;right:22px;font-size:30px;line-height:1.1}
#kiseki-b-design .b-cta:focus-visible{outline:3px solid #e3a400;outline-offset:4px}
#kiseki-b-design .b-section{margin:48px 0}
#kiseki-b-design .b-title{margin:0 0 26px;padding:4px 0 4px 16px;border-left:3px solid #0f1419;background:transparent;font-size:30px;font-weight:700;line-height:1.8;letter-spacing:.05em}
#kiseki-b-design strong{font-weight:700}
#kiseki-b-design .b-marker{background:linear-gradient(transparent 60%,#fff29a 60%);box-decoration-break:clone;-webkit-box-decoration-break:clone}
